PUBLIC_FILES = {'summary.json', 'report.html'}
STAGES = frozenset({'initializing','payload_verified','toolchains','pinned_inputs','forced_dispatch',
 'activation_sources','affine_sources','operator_gate','link_original','link_rebuilt','link_candidate',
 'link_diagnostic_candidate','prepared','browser_install','browser_gates',
 'input_gates','correctness_gates','provider_gates','callback_gates','primary_set_1','primary_set_2','primary_set_3',
 'post_gates','complete','failed','prepare_only','plan_only','self_test'})
HEX = re.compile(r'[0-9a-f]{64}')


def need(value, message):
    if not value: raise ValueError(message)


def digest(data): return hashlib.sha256(data).hexdigest()


def same(value, expected):
    if type(value) is not type(expected): return False
    if isinstance(value,dict): return value.keys()==expected.keys() and all(same(value[k],expected[k]) for k in value)
    if isinstance(value,(list,tuple)): return len(value)==len(expected) and all(same(a,b) for a,b in zip(value,expected))
    return value==expected


def load_payload():
    compressed = base64.b85decode(PAYLOAD_B85)
    need(digest(compressed) == PAYLOAD_SHA256, 'Embedded payload hash mismatch')
    decompressor = zlib.decompressobj()
    data = decompressor.decompress(compressed, 4_000_001)
    need(len(data) <= 4_000_000 and decompressor.eof and not decompressor.unconsumed_tail and not decompressor.unused_data, 'Payload expansion bound')
    rows = json.loads(data)
    need(type(rows) is dict and 10 <= len(rows) <= 64, 'Payload member count')
    result = {}
    for name, row in rows.items():
        p = PurePosixPath(name)
        need(not p.is_absolute() and str(p) == name and all(x not in ('', '.', '..') for x in p.parts), 'Unsafe embedded path')
        need(set(row) == {'sha256', 'base64'} and HEX.fullmatch(row['sha256']), 'Payload record schema')
        value = base64.b64decode(row['base64'], validate=True)
        need(len(value) <= 750_000 and digest(value) == row['sha256'], 'Embedded member mismatch')
        result[name] = value
    return result


def extract_payload(folder):
    folder = Path(folder)
    need(not folder.is_symlink(), 'Refuse symlink helper root')
    folder.mkdir(parents=True, exist_ok=True, mode=0o700)
    for name, data in load_payload().items():
        target = folder / name
        for parent in target.parents:
            if parent == folder: break
            need(not parent.is_symlink(), 'Refuse symlink helper parent')
        target.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        need(not target.is_symlink(), 'Refuse symlink in extracted helpers')
        if target.exists():
            need(target.is_file() and target.read_bytes() == data, 'Cached embedded source was modified')
        else:
            with target.open('xb') as stream: stream.write(data)
    return folder


def import_helper(folder, name):
    spec = importlib.util.spec_from_file_location('_affine_embedded_' + name, Path(folder) / (name + '.py'))
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def atomic_json(path, value):
    raw = (json.dumps(value, sort_keys=True, indent=2, allow_nan=False) + '\n').encode()
    temporary = path.with_suffix(path.suffix + '.tmp')
    with temporary.open('wb') as stream: stream.write(raw)
    temporary.replace(path)


def minimal_report(status, stage, *, exception_class=None):
    result = {'schema': DISTRIBUTION_SCHEMA, 'status': status, 'stage': stage,
              'distribution_sha256': digest(Path(__file__).read_bytes()), 'payload_sha256': PAYLOAD_SHA256,
              'browser_measurement_performed': None if status == 'failed' else False, 'primary_calls': None if status == 'failed' else 0,
              'cpu_time_series_measured': False}
    if exception_class is not None: result['exception_class'] = exception_class
    return result


def minimal_validate(report):
    required = {'schema','status','stage','distribution_sha256','payload_sha256','browser_measurement_performed','primary_calls','cpu_time_series_measured'}
    need(set(report) in (required, required | {'exception_class'}), 'Minimal report fields')
    need(report['schema'] == DISTRIBUTION_SCHEMA and report['status'] in {'plan_only','prepare_only','failed'}, 'Minimal report status')
    need(report['stage'] in STAGES and report['cpu_time_series_measured'] is False, 'Minimal report evidence')
    if report['status'] == 'failed':
        need(report['browser_measurement_performed'] is None and report['primary_calls'] is None, 'Failed run measurement counts unknown')
    else:
        need(report['browser_measurement_performed'] is False and type(report['primary_calls']) is int and report['primary_calls'] == 0, 'Unmeasured preparation evidence')
    need(HEX.fullmatch(report['distribution_sha256']) and report['payload_sha256'] == PAYLOAD_SHA256, 'Minimal provenance')
    if 'exception_class' in report:
        need(report['exception_class'] in {'ValueError','RuntimeError','PermissionError','FileNotFoundError','OSError','CalledProcessError','TimeoutExpired','KeyboardInterrupt','OtherError'}, 'Minimal error schema')


def minimal_html(report):
    minimal_validate(report)
    title = {'plan_only':'Plan verified; no build or measurement', 'prepare_only':'Source preparation complete; browser not run', 'failed':'Benchmark stopped; no valid speed conclusion'}[report['status']]
    return '<!doctype html><html lang="en"><meta charset="utf-8"><title>VOICEVOX affine milestone</title><style>body{font:16px system-ui;max-width:64rem;margin:3rem auto;padding:0 1rem}pre{overflow:auto;white-space:pre-wrap}</style><h1>Strict-FP32 affine-addressing browser milestone</h1><p>' + html.escape(title) + '</p><p>Original MR4 kernels, unchanged rebuilt MR4 kernels and affine-addressing candidate. Original CT, MR1, ReLU and dispatch remain unchanged. Normal tiering, revectorization OFF. CPU time series were not measured.</p><pre>' + html.escape(json.dumps(report, indent=2, sort_keys=True)) + '</pre></html>\n'


def make_envelope(manifest, benchmark, operator_probe=None):
    keys=('original','rebuilt','candidate','diagnostic_candidate')
    fields=('js_sha256','wasm_sha256','archive_sha256','complete_receipt_sha256','ordered_native_members_sha256','all_ordered_native_members_verified','timing_permitted')
    proof_fields=('affine_ir','affine_dependencies','activation_rebuilt_dependencies','activation_candidate_dependencies','source_addressing_edits_exact_reversible','ct_mr1_relu_and_dispatch_unchanged','affine_member_indices','unchanged_other_ordered_payloads','operator_dependencies')
    return {'schema':'affine-standalone-result-v1','status':benchmark['status'],
            'distribution_sha256':digest(Path(__file__).read_bytes()),'payload_sha256':PAYLOAD_SHA256,
            'source_refs':manifest['source_refs'],'toolchain_provisioning':manifest['toolchain_provisioning'],
            'artifacts':{key:{field:manifest['entries'][key][field] for field in fields} for key in keys},
            'source_proof':{key:manifest['source_proof'][key] for key in proof_fields},
            'operator_probe':operator_probe or {'executed':False,'performance_measured':False},'benchmark':benchmark}


def validate_operator_probe(value, required=False):
    need(type(value) is dict,'Operator proof schema')
    if value.get('executed') is False:
        need(not required and same(value,{'executed':False,'performance_measured':False}),'Missing actual operator gate')
        return
    fields={'executed','performance_measured','summary','wrapped_uint32_a_offset_cases','node_version','v8_version','node_sha256','node_provider','playwright_version','flags','js_sha256','wasm_sha256','stdout_sha256'}
    need(set(value)==fields and value['executed'] is True and value['performance_measured'] is False,'Operator proof schema')
    expected={'caseCount':7296,'originalMr4Cases':7200,'untouchedOtherDispatchCases':96,'outputLanesPerComparison':3497344,'exactMismatches':0,'outputPaddingAndTrailingGuards':True}
    need(same(value['summary'],expected) and type(value['wrapped_uint32_a_offset_cases']) is int and value['wrapped_uint32_a_offset_cases']==3648,'Actual operator exactness gate')
    need(type(value['node_version']) is str and re.fullmatch(r'\d+\.\d+\.\d+',value['node_version']),'Node identity')
    need(type(value['v8_version']) is str and re.fullmatch(r'[0-9A-Za-z.+-]{1,80}',value['v8_version']),'V8 identity')
    need(value['node_provider']=='playwright_bundled' and value['playwright_version']=='1.63.0' and value['node_version']=='24.21.0' and value['node_sha256']=='7fde7b8afa198da66257f42ee2001d874c7355631e6d1579a5fb5ef1f246df4c','Operator pinned runtime provenance')
    need(value['flags']==['--no-liftoff','--no-experimental-wasm-revectorize'],'Operator flags')
    need(all(type(value[k]) is str and HEX.fullmatch(value[k]) for k in ('node_sha256','js_sha256','wasm_sha256','stdout_sha256')),'Operator digests')


def validate_envelope(report):
    need(set(report)=={'schema','status','distribution_sha256','payload_sha256','source_refs','toolchain_provisioning','artifacts','source_proof','operator_probe','benchmark'},'Result envelope schema')
    need(report['schema']=='affine-standalone-result-v1' and report['status']==report['benchmark']['status'],'Envelope status')
    need(HEX.fullmatch(report['distribution_sha256']) and report['payload_sha256']==PAYLOAD_SHA256,'Distribution provenance')
    payload=load_payload(); pins=json.loads(payload['source/source_pins.json']); affine=json.loads(payload['affine_pins.json'])
    expected={'core_commit':'9b539761f3e152b966e08c2de0784129fe8cf68d','core_tar_sha256':'1b02f8d4743c70be2f501e51f47b4c248fa1160a7677c041ddf1e753353f7081',
              'ort_commit':pins['source_commit'],'ort_version':'1.23.2','xnn_commit':'fe98e0b93565382648129271381c14d6205255e3',
              'rust_version':'1.96.0','emsdk_version':'4.0.8',
              'affine_source_sha256':{f:p['candidate_source_sha256'] for f,p in affine['families'].items()},
              'source_bundle_manifest_sha256':affine['source_bundle_manifest_sha256'],
              'model_sha256':pins['model_sha256'],'query_sha256':pins['query_sha256']}
    need(same(report['source_refs'],expected),'Source provenance changed')
    tooling=report['toolchain_provisioning']
    need(set(tooling)=={'mode','original_ort_build_driver_sha256','configured_ort_build_driver_sha256','compiler_and_ir_pins_unchanged'},'Toolchain provisioning schema')
    driver='8217445502c9072362ee0961194747ad15f3828eeb17458fbc471b33e53465a1'
    need(tooling['mode'] in {'official_installer','verified_preinstalled_sdk'} and tooling['original_ort_build_driver_sha256']==driver and tooling['configured_ort_build_driver_sha256']=={'official_installer':driver,'verified_preinstalled_sdk':'36591f050ca7801e0088f9f47c120e8d62ca9a90651355f33d944a38743546f4'}[tooling['mode']] and tooling['compiler_and_ir_pins_unchanged'] is True,'Toolchain provisioning proof')
    keys=('original','rebuilt','candidate','diagnostic_candidate');need(set(report['artifacts'])==set(keys),'Artifact provenance conditions')
    hashes=('js_sha256','wasm_sha256','archive_sha256','complete_receipt_sha256','ordered_native_members_sha256')
    for key,row in report['artifacts'].items():
        need(set(row)==set(hashes)|{'all_ordered_native_members_verified','timing_permitted'},'Artifact schema')
        need(all(type(row[x]) is str and HEX.fullmatch(row[x]) for x in hashes),'Artifact digest')
        need(type(row['all_ordered_native_members_verified']) is int and row['all_ordered_native_members_verified']==1438 and row['timing_permitted'] is (key in keys[:3]),'Archive link proof')
        observed=report['benchmark'].get('artifacts',{}).get(key)
        if observed: need(all(observed[x]==row[x] for x in ('js_sha256','wasm_sha256')),'Measured artifact differs from prepared archive')
    proof=report['source_proof']
    need(set(proof)=={'affine_ir','affine_dependencies','activation_rebuilt_dependencies','activation_candidate_dependencies','source_addressing_edits_exact_reversible','ct_mr1_relu_and_dispatch_unchanged','affine_member_indices','unchanged_other_ordered_payloads','operator_dependencies'},'Source proof schema')
    need(proof['source_addressing_edits_exact_reversible'] is True and proof['ct_mr1_relu_and_dispatch_unchanged'] is True and same(proof['affine_member_indices'],[1236,1240]) and type(proof['unchanged_other_ordered_payloads']) is int and proof['unchanged_other_ordered_payloads']==1436,'Affine scope proof')
    need(type(proof['activation_rebuilt_dependencies']) is int and proof['activation_rebuilt_dependencies']==1291 and type(proof['activation_candidate_dependencies']) is int and proof['activation_candidate_dependencies']==1292,'Activation dependency proof')
    need(set(proof['affine_ir'])==set(proof['affine_dependencies'])=={'linear','minmax'},'Affine families')
    variants=('archived','rebuilt','candidate','diagnostic','probe-rebuilt','probe-candidate')
    for family,pin in affine['families'].items():
        ir={'all_original_rebuilt_ir_equal_except_two_source_headers':True,'complete_normalized_ir_sha256':{key:pin[key+'_normalized_ir_sha256'] for key in variants},'strict_simd_no_relaxed_simd_or_fma':True,'timed_candidate_without_diagnostic_instrumentation':True}
        need(same(proof['affine_ir'][family],ir),'Complete affine IR proof changed')
        deps=proof['affine_dependencies'][family];need(set(deps)==set(variants[1:]),'Affine dependency variant proof')
        for key,row in deps.items():
            need(set(row)=={'raw_observations','canonical_files','complete_canonical_dependency_hash_bytes_equal'},'Affine dependency proof schema')
            need(row['complete_canonical_dependency_hash_bytes_equal'] is True and type(row['raw_observations']) is int and type(row['canonical_files']) is int and row['raw_observations']==len(pin[key+'_dependencies']) and 1<=row['canonical_files']<=row['raw_observations'],'Affine dependency proof counts')
    dep=proof['operator_dependencies']
    need(set(dep)=={'raw_observations','canonical_files','complete_canonical_dependency_hash_bytes_equal'},'Operator dependency proof schema')
    need(dep['complete_canonical_dependency_hash_bytes_equal'] is True and type(dep['raw_observations']) is int and type(dep['canonical_files']) is int and dep['raw_observations']==len(affine['operator_dependencies']) and 1<=dep['canonical_files']<=dep['raw_observations'],'Operator dependency proof counts')
    validate_operator_probe(report['operator_probe'],required=report['status']=='complete')


def report_tools(payload, report):
    if report.get('schema') == 'affine-standalone-result-v1':
        validate_envelope(report)
        rendered = report_tools(payload,report['benchmark'])
        need(rendered.count('</html>')==1, 'Expected one report HTML root')
        provenance={k:v for k,v in report.items() if k!='benchmark'}
        detail='<h2>Source and archive provenance</h2><details><summary>Exact standalone source, build and 1438-member link evidence</summary><pre>'+html.escape(json.dumps(provenance,sort_keys=True,indent=2))+'</pre></details>'
        return rendered.replace('</body>',detail+'</body>') if '</body>' in rendered else rendered.replace('</html>',detail+'</html>')
    if report.get('schema') == DISTRIBUTION_SCHEMA:
        minimal_validate(report)
        return minimal_html(report)
    helper = import_helper(payload, 'affine_browser')
    helper.validate_public_report(report)
    return helper.render_html(report)


def validate_output(output, payload):
    need(output.is_dir() and not output.is_symlink(), 'Public output directory')
    need({x.name for x in output.iterdir()} == PUBLIC_FILES, 'Unexpected file in public output directory')
    for name in PUBLIC_FILES:
        p = output / name
        need(p.is_file() and not p.is_symlink() and p.stat().st_size <= 2_000_000, 'Public output file bound/type')
    raw_summary = (output / 'summary.json').read_text()
    def no_duplicates(pairs):
        value = {}
        for key, item in pairs:
            need(key not in value, 'Duplicate JSON key')
            value[key] = item
        return value
    report = json.loads(raw_summary, object_pairs_hook=no_duplicates)
    need(raw_summary == json.dumps(report, sort_keys=True, indent=2, allow_nan=False) + '\n', 'Public summary must be canonical JSON')
    expected = report_tools(payload, report)
    need((output / 'report.html').read_text() == expected, 'HTML does not exactly render validated summary')
    return report


def save_public(output, payload, report):
    rendered = report_tools(payload, report)
    atomic_json(output / 'summary.json', report)
    (output / 'report.html').write_text(rendered)
    validate_output(output, payload)


def plan():
    rows = load_payload()
    return {'schema': DISTRIBUTION_SCHEMA, 'embedded_files': len(rows),
        'payload_sha256': PAYLOAD_SHA256, 'pinned_fixture_frames': 962,
        'threads': {'ort': 1, 'xnnpack': 2}, 'seed': 1729,
        'primary_conditions': ['original','rebuilt','candidate'],
        'fresh_sets': 3, 'paired_rounds_per_set': 5, 'primary_calls': 45,
        'completed_primary_calls': 0, 'builds_performed': False, 'inference_performed': False,
        'downloads_performed': False, 'cpu_time_series_measured': False}


def self_test(payload):
    # Tests are embedded with the implementation and never require browsers/builds.
    sys.modules['_affine_distribution'] = sys.modules[__name__]
    sys.path.insert(0, str(payload)); sys.path.insert(0, str(payload / 'source'))
    suite = unittest.defaultTestLoader.discover(str(payload), pattern='test_affine_*.py')
    need(suite.countTestCases() >= 8, 'Embedded tests unexpectedly absent')
    with io.StringIO() as buffer:
        result = unittest.TextTestRunner(stream=buffer, verbosity=0).run(suite)
        if not result.wasSuccessful():
            # Failure details remain private in worker logs, never in public output.
            raise RuntimeError('Embedded tests failed')
    return {'tests': result.testsRun, 'skipped': len(result.skipped), 'passed': True, 'browser_calls': 0, 'builds': 0}


def worker(args):
    payload = Path(args.payload)
    progress = Path(args.progress)
    def stage(value):
        need(value in STAGES, 'Unknown progress stage')
        atomic_json(progress, {'stage': value})
    stage('payload_verified')
    with (Path(args.cache) / 'affine-run.lock').open('w') as lock:
        import fcntl
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        prepare = import_helper(payload, 'affine_prepare')
        manifest = prepare.prepare(payload, Path(args.cache), stage, args.sdk_path)
        atomic_json(Path(args.private) / 'prepared-manifest.json', manifest)
        operator_probe = None
        if args.prepare_only:
            report = minimal_report('prepare_only', 'prepared')
        else:
            stage('operator_gate')
            operator_probe = prepare.run_operator_probe(manifest, Path(args.private))
            validate_operator_probe(operator_probe, required=True)
            atomic_json(Path(args.private) / 'operator-receipt.json', operator_probe)
            stage('browser_install')
            subprocess.run([sys.executable, '-m', 'playwright', 'install', 'chromium'], check=True)
            browser = import_helper(payload, 'affine_browser')
            def browser_stage(record):
                need(set(record)=={'stage','completed_primary_calls'} and type(record['completed_primary_calls']) is int and 0<=record['completed_primary_calls']<=45, 'Browser stage schema')
                stage(record['stage'])
            report = browser.run(manifest, payload, Path(args.private), browser_stage)
        report = make_envelope(manifest, report, operator_probe)
        atomic_json(Path(args.result), report)
        stage('complete')


def recover_checkpoint(payload, private):
    checkpoint=private/'browser-checkpoint.json'; manifest=private/'prepared-manifest.json'
    if not checkpoint.is_file() or not manifest.is_file() or checkpoint.stat().st_size>2_000_000:
        return None
    try:
        report=json.loads(checkpoint.read_text())
        report.update(status='incomplete',measurement_valid=False,error_code='interrupted',summary=None)
        helper=import_helper(payload,'affine_browser'); helper.validate_public_report(report)
        operator=private/'operator-receipt.json'
        value=make_envelope(json.loads(manifest.read_text()),report,json.loads(operator.read_text()) if operator.is_file() else None)
        report_tools(payload,value)
        return value
    except Exception:
        return None


def safe_exception(error):
    name = type(error).__name__
    return name if name in {'ValueError','RuntimeError','PermissionError','FileNotFoundError','OSError','CalledProcessError','TimeoutExpired','KeyboardInterrupt'} else 'OtherError'


def parser():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--cache-dir', type=Path, default=Path(os.environ.get('XDG_CACHE_HOME', Path.home() / '.cache')) / 'voicevox-affine-addressing', help='Private reusable downloads, models, toolchains, builds and logs; never upload this directory')
    p.add_argument('--sdk-path', type=Path, help='Optional installed SDK4.0.8 with literal LLVM_ROOT/BINARYEN_ROOT/NODE_JS config; exact compiler/IR pins remain mandatory; adaptation is recorded')
    p.add_argument('--output', type=Path, default=Path('affine-addressing-report'), help='New or empty public output directory; contains only summary.json and report.html')
    p.add_argument('--prepare-only', action='store_true', help='Build and verify all three controls and separate diagnostics; never launch browser or infer')
    p.add_argument('--dry-run', action='store_true', help='Offline embedded source/pin validation and design plan only; no builds or inference')
    p.add_argument('--self-test', action='store_true', help='Run embedded offline source, schedule, privacy and reporting tests')
    p.add_argument('--validate-report', type=Path, help='Strictly revalidate summary plus exact HTML before publishing these two files')
    p.add_argument('--extract-helpers', type=Path, help='Extract hash-verified embedded source helpers for inspection; no download/build/inference')
    p.add_argument('--_worker', action='store_true', help=argparse.SUPPRESS)
    for key in ('payload','progress','private','result','cache'):
        p.add_argument('--_' + key, dest=key, help=argparse.SUPPRESS)
    return p


def main(argv=None):
    args = parser().parse_args(argv)
    if args._worker:
        return worker(args)
    if args.extract_helpers:
        extract_payload(args.extract_helpers.resolve())
        print('AFFINE_SOURCE ' + json.dumps({'embedded_source_verified':True,'files':len(load_payload())}, sort_keys=True))
        return 0
    with tempfile.TemporaryDirectory(prefix='affine-embedded-tests-') as temp:
        payload = extract_payload(Path(temp))
        if args.self_test:
            print('AFFINE_SELF_TEST ' + json.dumps(self_test(payload), sort_keys=True)); return 0
        if args.validate_report:
            validate_output(args.validate_report.resolve(), payload)
            print('AFFINE_VALIDATED ' + json.dumps({'files':sorted(PUBLIC_FILES),'valid':True}, sort_keys=True)); return 0
        if args.dry_run:
            print('AFFINE_PLAN ' + json.dumps(plan(), sort_keys=True)); return 0
    cache = args.cache_dir.expanduser().resolve(); output = args.output.expanduser().resolve()
    need(not output.is_relative_to(cache) and not cache.is_relative_to(output), 'Public output and private cache must not overlap')
    need(not output.exists() or (output.is_dir() and not any(output.iterdir())), 'Refuse to overwrite existing public output')
    os.umask(0o077)
    cache.mkdir(parents=True, exist_ok=True, mode=0o700); cache.chmod(0o700)
    output.mkdir(parents=True, exist_ok=True, mode=0o700)
    payload = extract_payload(cache / ('embedded-' + PAYLOAD_SHA256[:16]))
    private = Path(tempfile.mkdtemp(prefix='run-', dir=cache))
    progress = private / 'progress.json'; result = private / 'result.json'; log = private / 'private.log'
    env = dict(os.environ)
    env.pop('PYTHONOPTIMIZE', None); env['PYTHONUNBUFFERED'] = '1'
    env['PLAYWRIGHT_BROWSERS_PATH'] = str(cache / 'playwright')
    command = [sys.executable, str(Path(__file__).resolve()), '--_worker', '--_payload', str(payload), '--_progress', str(progress), '--_private', str(private), '--_result', str(result), '--_cache', str(cache)]
    if args.prepare_only: command += ['--prepare-only']
    if args.sdk_path: command += ['--sdk-path', str(args.sdk_path.expanduser().resolve())]
    stage = 'initializing'; child = None
    try:
        with log.open('wb') as stream:
            child = subprocess.Popen(command, stdout=stream, stderr=subprocess.STDOUT, env=env, start_new_session=True)
            while child.poll() is None:
                if progress.exists():
                    item = json.loads(progress.read_text())
                    need(set(item) == {'stage'} and item['stage'] in STAGES, 'Private progress schema changed')
                    if item['stage'] != stage:
                        stage = item['stage']; print('AFFINE_STAGE ' + json.dumps({'stage':stage}, sort_keys=True), flush=True)
                time.sleep(2)
            need(child.returncode == 0 and result.is_file(), 'Benchmark worker did not complete')
        report = json.loads(result.read_text())
        save_public(output, payload, report)
        print('AFFINE_FINISHED ' + json.dumps({'status':report['status'],'validated_public_files':sorted(PUBLIC_FILES)}, sort_keys=True))
        return 0 if report['status'] in {'complete','prepare_only'} else 1
    except BaseException as error:
        if child is not None and child.poll() is None:
            import signal
            os.killpg(child.pid, signal.SIGTERM)
            try: child.wait(timeout=15)
            except subprocess.TimeoutExpired:
                os.killpg(child.pid, signal.SIGKILL); child.wait()
        report = recover_checkpoint(payload,private) or minimal_report('failed', stage, exception_class=safe_exception(error))
        save_public(output, payload, report)
        print('AFFINE_FAILED ' + json.dumps({'stage':stage,'exception_class':safe_exception(error)}, sort_keys=True), file=sys.stderr)
        return 1


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as error:
        print('AFFINE_FAILED ' + json.dumps({'stage':'initializing','exception_class':safe_exception(error)}, sort_keys=True), file=sys.stderr)
        raise SystemExit(1)
